package com.flovex.shop;
import org.bukkit.*;import org.bukkit.command.*;import org.bukkit.configuration.ConfigurationSection;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.inventory.InventoryClickEvent;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.plugin.java.JavaPlugin;import java.util.*;
public final class ShopPluginMc extends JavaPlugin implements Listener{
 private final Map<UUID,State> states=new HashMap<>();private final Map<UUID,Integer> pages=new HashMap<>();private String main;
 public void onEnable(){saveDefaultConfig();main=color(getConfig().getString("menu.title","&8Shop"));getServer().getPluginManager().registerEvents(this,this);}
 public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(c.getName().equalsIgnoreCase("flovexshop")){if(!s.hasPermission("flovexshop.admin")){s.sendMessage(color("&cNo permission."));return true;}if(a.length>0&&a[0].equalsIgnoreCase("reload")){reloadConfig();main=color(getConfig().getString("menu.title","&8Shop"));s.sendMessage(color("&aConfig reloaded."));}else s.sendMessage("/flovexshop reload");return true;}if(!(s instanceof Player p))return true;if(!p.hasPermission("flovexshop.use")){p.sendMessage(color("&cNo permission."));return true;}if(a.length>0)openCat(p,a[0],0);else openMain(p);return true;}
 private void openMain(Player p){Inventory i=Bukkit.createInventory(null,27,main);fill(i,Material.GRAY_STAINED_GLASS_PANE);ConfigurationSection cs=getConfig().getConfigurationSection("categories");if(cs!=null)for(String id:cs.getKeys(false)){ConfigurationSection c=cs.getConfigurationSection(id);if(c!=null&&c.getBoolean("enabled",true)){int slot=c.getInt("slot",13);if(slot>=0&&slot<27)i.setItem(slot,make(c.getString("icon","CHEST"),c.getString("name",id),c.getString("lore","")));}}p.openInventory(i);}
 private void openCat(Player p,String id,int page){ConfigurationSection c=getConfig().getConfigurationSection("categories."+id);if(c==null){openMain(p);return;}if(id.equalsIgnoreCase(getConfig().getString("shard-category","shards"))){p.performCommand(getConfig().getString("shard-command","shardshop"));return;}pages.put(p.getUniqueId(),page);Inventory i=Bukkit.createInventory(null,54,color(c.getString("title","&8"+id)));fill(i,Material.GRAY_STAINED_GLASS_PANE);ConfigurationSection products=c.getConfigurationSection("items");List<String> keys=products==null?new ArrayList<>():new ArrayList<>(products.getKeys(false));for(int n=0;n<45&&page*45+n<keys.size();n++){ConfigurationSection pr=products.getConfigurationSection(keys.get(page*45+n));if(pr!=null)i.setItem(n,product(pr,keys.get(page*45+n)));}i.setItem(45,make("RED_DYE","&cBack","&7Categories"));if(page>0)i.setItem(46,make("ARROW","&ePrevious page",""));i.setItem(49,make("PAPER","&fPage &e"+(page+1),""));if((page+1)*45<keys.size())i.setItem(52,make("ARROW","&eNext page",""));p.openInventory(i);}
 private void buyMenu(Player p,String cat,String key,int amount,int page){ConfigurationSection pr=getConfig().getConfigurationSection("categories."+cat+".items."+key);if(pr==null)return;amount=Math.max(1,Math.min(pr.getInt("max-amount",64),amount));double price=pr.getDouble("price",0)*amount;Inventory i=Bukkit.createInventory(null,27,color(getConfig().getString("buy-menu.title","&8Purchase")));fill(i,Material.GRAY_STAINED_GLASS_PANE);i.setItem(10,make("RED_CANDLE","&c-1",""));i.setItem(11,make("RED_CANDLE","&c-10",""));i.setItem(12,make("RED_CANDLE","&c-64",""));ItemStack preview=product(pr,key);ItemMeta meta=preview.getItemMeta();if(meta!=null){List<String> lore=meta.hasLore()?new ArrayList<>(meta.getLore()):new ArrayList<>();lore.add(color("&7Amount: &f"+amount));lore.add(color("&7Total: &a"+money(price)+" "+getConfig().getString("currency-name","$")));meta.setLore(lore);preview.setItemMeta(meta);}i.setItem(13,preview);i.setItem(14,make("GREEN_CANDLE","&a+1",""));i.setItem(15,make("GREEN_CANDLE","&a+10",""));i.setItem(16,make("GREEN_CANDLE","&a+64",""));i.setItem(18,make("RED_DYE","&cCancel",""));i.setItem(26,make("GREEN_DYE","&aConfirm","&7"+money(price)));states.put(p.getUniqueId(),new State(cat,key,amount,page));p.openInventory(i);}
 @EventHandler public void onClick(InventoryClickEvent e){if(!(e.getWhoClicked() instanceof Player p)||e.getClickedInventory()!=e.getView().getTopInventory())return;String t=e.getView().getTitle();if(t.equals(main)){e.setCancelled(true);ItemStack cur=e.getCurrentItem();if(cur==null||!cur.hasItemMeta())return;ConfigurationSection cs=getConfig().getConfigurationSection("categories");if(cs!=null)for(String id:cs.getKeys(false))if(color(getConfig().getString("categories."+id+".name",id)).equals(cur.getItemMeta().getDisplayName())){openCat(p,id,0);return;}return;}
 ConfigurationSection cs=getConfig().getConfigurationSection("categories");String cat=null;if(cs!=null)for(String id:cs.getKeys(false))if(t.equals(color(getConfig().getString("categories."+id+".title","&8"+id))))cat=id;
 if(cat!=null){e.setCancelled(true);ItemStack cur=e.getCurrentItem();if(cur==null||cur.getType().isAir())return;if(cur.getType()==Material.RED_DYE){openMain(p);return;}if(cur.getType()==Material.ARROW){openCat(p,cat,e.getSlot()==46?Math.max(0,pages.getOrDefault(p.getUniqueId(),0)-1):pages.getOrDefault(p.getUniqueId(),0)+1);return;}if(e.getSlot()>=45)return;ConfigurationSection ps=cs.getConfigurationSection(cat+".items");if(ps==null)return;List<String> ks=new ArrayList<>(ps.getKeys(false));int index=pages.getOrDefault(p.getUniqueId(),0)*45+e.getSlot();if(index<ks.size())buyMenu(p,cat,ks.get(index),1,pages.getOrDefault(p.getUniqueId(),0));return;}
 if(t.equals(color(getConfig().getString("buy-menu.title","&8Purchase")))){e.setCancelled(true);State st=states.get(p.getUniqueId());if(st==null)return;ItemStack cur=e.getCurrentItem();if(cur==null)return;String n=cur.hasItemMeta()?cur.getItemMeta().getDisplayName():"";int d=0;if(cur.getType()==Material.RED_CANDLE)d=n.contains("64")?-64:n.contains("10")?-10:-1;if(cur.getType()==Material.GREEN_CANDLE)d=n.contains("64")?64:n.contains("10")?10:1;if(d!=0){buyMenu(p,st.cat,st.key,st.amount+d,st.page);return;}if(cur.getType()==Material.RED_DYE){states.remove(p.getUniqueId());openCat(p,st.cat,st.page);return;}if(cur.getType()==Material.GREEN_DYE){states.remove(p.getUniqueId());complete(p,st);}}}
 private void complete(Player p,State s){ConfigurationSection pr=getConfig().getConfigurationSection("categories."+s.cat+".items."+s.key);if(pr==null)return;int qty=s.amount;double total=pr.getDouble("price",0)*qty;String payment=getConfig().getString("payment-command","");if(!payment.isBlank())console(payment.replace("%player%",p.getName()).replace("%price%",money(total)).replace("%amount%",String.valueOf(qty)));String cmd=pr.getString("command","");if(!cmd.isBlank()){for(String line:cmd.split("\\n"))console(line.replace("%player%",p.getName()).replace("%amount%",String.valueOf(qty)).replace("%price%",money(total)).replace("%product%",s.key));}else{Material m=Material.matchMaterial(pr.getString("material","STONE"));if(m!=null){ItemStack reward=new ItemStack(m,qty);p.getInventory().addItem(reward).values().forEach(x->p.getWorld().dropItemNaturally(p.getLocation(),x));}}p.sendMessage(color(getConfig().getString("messages.purchased","&aBought %amount%x %item% for %price%.").replace("%amount%",String.valueOf(qty)).replace("%item%",s.key).replace("%price%",money(total))));p.closeInventory();}
 private ItemStack product(ConfigurationSection c,String id){return make(c.getString("material","STONE"),c.getString("name","&f"+id),c.getString("lore","&7Price: &a%price%").replace("%price%",money(c.getDouble("price",0))+" "+getConfig().getString("currency-name","$")));}
 private ItemStack make(String mat,String name,String lore){Material m=Material.matchMaterial(mat);if(m==null)m=Material.BARRIER;ItemStack i=new ItemStack(m);ItemMeta im=i.getItemMeta();if(im!=null){im.setDisplayName(color(name));if(lore!=null&&!lore.isBlank())im.setLore(Arrays.stream(lore.split("\\n")).map(this::color).toList());i.setItemMeta(im);}return i;}
 private void fill(Inventory i,Material m){ItemStack f=make(m.name()," ","");for(int n=0;n<i.getSize();n++)if(i.getItem(n)==null)i.setItem(n,f);}private void console(String cmd){Bukkit.dispatchCommand(Bukkit.getConsoleSender(),cmd.startsWith("/")?cmd.substring(1):cmd);}private String color(String s){return ChatColor.translateAlternateColorCodes('&',s==null?"":s);}private String money(double d){return String.format(Locale.US,"%,.2f",d);}private record State(String cat,String key,int amount,int page){}
}